# Hypothesis: maximal solid rectangles of uniform nonzero color with both dims>=2? Check each changed comp fully inside a rect of same color in input.
inp=np.array(G['Demo pair 1 input']); out=np.array(G['Demo pair 1 output'])
H,W=inp.shape
def isrect(cells):
    r0,r1,c0,c1=np.array(cells).min(0),np.array(cells).max(0)
    return len(set(cells))==((r1-r0+1)*(c1-c0+1))
changed={(int(r),int(c)) for r,c in np.argwhere(out==4)}
for r,c in sorted(changed)[:3]:
    print(inp[r,c], inp[max(0,r)-1:,:])
print('color of changed cells:', {inp[r,c] for r,c in changed})
# Are there solid uniform rects >=2x2 that did NOT change?
from collections import defaultdict
rects=[]
seen=set()
for i in range(H):
    for j in range(W):
        if inp[i,j]!=0 and (i,j) not in seen:
            c=inp[i,j]; stack=[(i,j)]
            while stack:
                x,y=stack.pop()
                if (x,y) in seen or inp[x,y]!=c: continue
                seen.add((x,y)); stack.extend([(x+1,y),(x-1,y),(x,y+1),(x,y-1)])
            pts=list(seen)
            for p in pts: del seen[p]
            if len(pts)>1:
                rects.append((c,tuple(min(p) for p in [p[0] for p in []]))) 
rects=None

import numpy as np, itertools
from collections import Counter
inp=np.array(G['Demo pair 1 input']); out=np.array(G['Demo pair 1 output'])
H,W=inp.shape
changed={(int(r),int(c)) for r,c in np.argwhere(out==4)}
def rects_of(inp,minh=min(2)):
    res=[]; seen=set()
    for i in range(inp.shape[0]):
        for j in range(inp.shape[1]):
            if inp[i,j]==0 or (i,j) in seen: continue
            c=inp[i,j]
            h=1
            while i+h<inp.shape[0] and inp[i+h,j]==c: h+=1
            w=1
            while j+w<inp.shape[1] and inp[i,j+w]==c: w+=1
            # all maximal solid rects starting here of size hh x ww with both>=minh
            for hh in range(minh,h+1):
                for ww in range(minh,w+1):
                    if not all(inp[r_,k_]==c for r_ in range(i,i+hh) for k_ in range(j,j+ww)): continue
                    maxr=i+hh-1; maxc=j+ww-1
                    ext_d = maxr+1<inp.shape[0] and all(inp[maxr+1,k]==c for k in range(j,maxc+1))
                    ext_c = maxc+1<inp.shape[1] and all(inp[r_,maxc+1]==c for r_ in range(i,maxr+1))
                    if not(ext_d or ext_c):
                        res.append((c,i,j,hh,ww))
    return res
R=rects_of(inp)
for c,r0,c0,h,w in R:
    cells={(r,k) for r in range(r0,r0+h) for k in range(c0,c0+w)}
    tag='CHANGED' if cells<=changed else ('kept' if cells&changed else 'nonech')
    print(c,(r0,c0,h,w),'area',h*w,tg:=tag)

