import numpy as np
from collections import deque
D1I=np.array(G['Demo pair 1 input']); D1O=np.array(G['Demo pair 1 output'])
D2I=np.array(G['Demo pair 2 input']); D2O=np.array(G['Demo pair 2 output'])
def comps(mask):
    seen=np.zeros_like(mask,bool); out=[]
    for r,c in zip(*np.where(mask)):
        if seen[r,c]: continue
        q=deque([(r,c)]); seen[r,c]=True; comp=[]
        while q:
            x,y=q.popleft(); comp.append((x,y))
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<len(mask) and 0<=ny<len(mask[0]) and mask[nx,ny] and not seen[nx,ny]:
                        seen[nx,ny]=True; q.append((nx,ny))
        out.append(comp)
    return out
for name,(ii,oo) in [('d1',(D1I,D1O)),('d2',(D2I,D2O))]:
    m=(oo!=ii)
    print('===',name,'n changed',m.sum())
    for comp in comps(m):
        rs=[r for r,_ in comp]; cs=[c for _,c in comp]
        r0,r1_,c0,c1_=min(rs),max(rs),min(cs),max(cs)
        hgt,w0=r1_-r0+1,c1_-c0+1
        print(len(comp),'fill %.3f'%(len(comp)/(hgt*w0)),'bbox',(int(r0),int(c0),int(r1_),int(c1_)))
        sub=ii[r0:r1_+1,c0:c1_+1]
        for row in sub: print(''.join(str(x) for x in row))
